-- Safe rollback disables alerts rather than restoring the known-unscoped function.
BEGIN; DO $check$ DECLARE d text; BEGIN IF to_regprocedure('public.stock_alerts_summary(integer)') IS NULL THEN RAISE EXCEPTION 'Missing stock_alerts_summary'; END IF; SELECT lower(pg_catalog.pg_get_functiondef(oid)) INTO d FROM pg_catalog.pg_proc WHERE oid=to_regprocedure('public.stock_alerts_summary(integer)'); IF position('tenant_private.current_shop_id()' IN d)=0 THEN RAISE EXCEPTION 'Not the scoped alert function'; END IF; END; $check$; REVOKE ALL ON FUNCTION public.stock_alerts_summary(integer) FROM PUBLIC,anon,authenticated,service_role; COMMIT;
